        sign = -1
        s = s[1:]
    elif s[0] == '+':
        s = s[1:]
    elif not s[0].isdigit():
        raise ValueError('invalid digit')

    value = 0
    for char in s:
        if not char.isdigit():
            raise ValueError('invalid digit')
        value = value * 10 + int(char)

    return sign * value
